import{_ as s,o,c as l,ag as r}from"./chunks/framework.D2veAa-g.js";const p=JSON.parse('{"title":"章节练习 错题集","description":"","frontmatter":{"title":"章节练习 错题集"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/章节练习 错题集.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/章节练习 错题集.md","lastUpdated":null}'),n={name:"架构师 在线刷题/51CT0题库 章节练习/章节练习 错题集.md"};function a(e,t,i,_,g,c){return o(),l("div",null,[...t[0]||(t[0]=[r('<h2 id="q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" tabindex="-1">Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。 <a class="header-anchor" href="#q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" aria-label="Permalink to &quot;Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> SOA风格</li><li><strong>B.</strong> 虚拟机风格</li><li><strong>C.</strong> MVC风格</li><li><strong>D.</strong> 平台/插件风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>A：SOA风格主要用于企业集成<br> B：错误，虚拟机风格用于解释器或专家系统<br> C：正确，MVC风格专门用于用户交互程序的设计<br> D：错误，平台/插件风格主要用于具有插件扩展功能的应用程序</p><p>【教材依据】MVC风格用于用户交互程序的设计。因此本题的正确答案是C。</p><ul><li><strong>SOA 风格</strong>：面向服务，适用于企业系统集成、跨系统调用。</li><li><strong>虚拟机风格</strong>：基于解释器、规则系统，适合规则引擎、脚本语言环境。</li><li><strong>MVC 风格</strong>：明确将交互系统分为 <strong>模型（Model）</strong>、<strong>视图（View）</strong>、<strong>控制器（Controller）</strong>，专为<strong>用户交互频繁、界面多变</strong>的应用设计。</li><li><strong>平台/插件风格</strong>：核心系统 + 插件式扩展，适合 IDE、浏览器等。</li></ul></div></details>',3)])])}const u=s(n,[["render",a]]);export{p as __pageData,u as default};
